db.accounts??=db.shops.map((s,i)=>({id:'USER-'+s.id,name:['فهد العتيبي','أحمد السالم','ريم خالد'][i]||s.name,email:`${s.id}@example.com`,phone:['0501000001','0501000002','0501000003'][i]||'',shop:s.id,created:Date.now(),subscription:{status:i===1?'pending':'active',expires:i===1?null:Date.now()+86400000*30,period:'month'}}));
db.tokens??=[];db.adminLogs??=[];db.settings??={whatsapp:'966535979538'};db.settings.whatsapp='966535979538';
db.accounts.forEach((a,i)=>{if(!a.phone)a.phone=['0501000001','0501000002','0501000003'][i]||'';});
let newBusiness=false;let loginType='owner',loginStep='phone',loginPhone='',loginName='',loginBusiness='';
let signedAccount=db.accounts.find(a=>a.shop===db.shop)?.id||db.accounts[0].id,publicPage=new URLSearchParams(location.search).has('join')?'':'home';
const account=()=>db.accounts.find(a=>a.id===signedAccount);
const shopAccount=()=>db.accounts.find(a=>a.shop===(shop().business||shop().id));
function statusOf(a){if(a.subscription.status==='suspended')return 'suspended';if(!a.subscription.expires)return 'pending';return a.subscription.expires>Date.now()?'active':'expired';}
const statusNames={active:'مفعّل',pending:'بانتظار التفعيل',expired:'منتهي',suspended:'موقوف'};
const dateLabel=t=>t?new Date(t).toLocaleDateString('ar-SA',{year:'numeric',month:'short',day:'numeric',timeZone:'Asia/Riyadh'}):'—';
function canOperate(){return statusOf(shopAccount())==='active'&&shop().status==='active';}
function extendDate(base,period){const d=new Date(base),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+(period==='year'?12:1));const max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,max));return d.getTime();}
function audit(action,a,extra=''){db.adminLogs.unshift({id:crypto.randomUUID(),action,user:a?.name||'إدارة المنصة',extra,time:Date.now()});}
function activate(a,period,source='admin'){a.subscription={status:'active',period,expires:extendDate(Math.max(Date.now(),a.subscription.expires||0),period)};const s=db.shops.find(s=>s.id===a.shop);s.status='active';audit(source==='token'?'تفعيل بتوكن':'تفعيل / تجديد',a,period==='year'?'سنة':'شهر');save();}
function whatsapp(){const a=account();const message=`مرحبًا، أرغب في الاشتراك في رِجعة بسعر 199 ريال للشهر وبطاقات غير محدودة.${a?`\nمعرّف الحساب: ${a.id}\nالنشاط: ${db.shops.find(s=>s.id===a.shop)?.name}\nالجوال: ${a.phone}`:''}`;window.location.assign(`https://wa.me/${db.settings.whatsapp}?text=${encodeURIComponent(message)}`);}
navAdmin.splice(1,0,['accounts','users','المستخدمون والاشتراكات']);navAdmin.push(['tokens','shield','توكنات التفعيل'],['adminlog','clock','سجل الإدارة']);navOwner.push(['subscription','gift','الاشتراك']);
const originalRender=render,originalOwnerHTML=ownerHTML,originalAdminHTML=adminHTML,originalScan=processScan;
ownerHTML=function(){if(view==='subscription')return subscriptionHTML();return originalOwnerHTML();};
adminHTML=function(){if(view==='overview'&&!db.shops.length)return head('إدارة رِجعة','المستخدمون والاشتراكات','تظهر الأنشطة هنا بعد تسجيل أصحابها.')+'<button class="btn primary" data-action="nav" data-view="accounts">عرض المستخدمين</button>';if(view==='accounts')return accountsHTML();if(view==='tokens')return tokensHTML();if(view==='adminlog')return adminLogHTML();return originalAdminHTML();};
processScan=function(code){if(!canOperate()){toast('يلزم تفعيل الاشتراك لتسجيل الزيارات.');return;}originalScan(code);};
function publicNav(){return `<header class="public-nav"><button class="brand public-brand" data-action="home"><span class="brand-symbol">${icon('refresh')}</span><span>رِجعة</span></button><div class="actions"><button class="btn quiet" data-action="demo-admin">تجربة الأدمن</button><button class="btn secondary" data-action="login">تسجيل الدخول</button></div></header>`;}
function homeHTML(){return `${publicNav()}<main class="landing"><section class="landing-intro"><span class="landing-kicker">ولاء بسيط. في محفظة عميلك.</span><h1>خلّ كل زيارة<br>سببًا للرجعة.</h1><p>بطاقة باسم نشاطك، أختام لكل زيارة، ومكافأة تستاهل الرجعة.<br>صمّمها، شاركها، وخلّ فريقك يسجل الزيارات بسهولة.</p><div class="actions"><button class="btn primary" data-action="login">جرّب لوحة نشاطك</button><button class="btn secondary" data-action="whatsapp">اشترك عبر واتساب</button></div></section><section class="showcase" aria-label="نماذج بطاقات الولاء">${[templates[1],templates[0],{...templates[3],name:'حلاق الحي',category:'حلاق',reward:'حلاقة مجانية'}].map((t,i)=>`<div class="showcase-item showcase-${i}">${cardHTML(t)}<p>${esc(t.category)}</p></div>`).join('')}</section><section class="pricing" id="pricing"><div class="pricing-copy"><div class="eyebrow">اشتراك واحد، واضح.</div><h2>كل ما يحتاجه برنامج ولائك.</h2><p>بدون حساب عدد البطاقات، وبدون تعقيد الباقات.</p><div class="feature-list">${['بطاقات ولاء غير محدودة','تنسيق القوالب والألوان والخلفيات','إضافة فريقك وإدارة الموظفين','واجهة سريعة لمسح البطاقات','إدارة العملاء والأختام والمكافآت','سجل واضح لكل عملية'].map(t=>`<div>${icon('check')} ${t}</div>`).join('')}</div></div><article class="price-card"><span class="pill">اشتراك رِجعة</span><div class="price">١٩٩ <span>ريال / شهر</span></div><p>بطاقات غير محدودة لنشاطك</p><button class="btn lime full" data-action="whatsapp">اشترك عبر واتساب</button><small>الدفع والتفعيل بالتواصل مع الإدارة عبر واتساب.</small><button class="price-login" data-action="login">تصفح اللوحة قبل الاشتراك</button></article></section><section class="landing-how"><h2>ثلاث خطوات، والبرنامج جاهز.</h2><div>${[['١','صمّم بطاقتك','اختر قالبًا يناسب نشاطك وعدّل هويته.'],['٢','شاركها مع العملاء','يسجل العميل برقم جواله ويحصل على بطاقته.'],['٣','سجّل الزيارات','الموظف يمسح البطاقة، والعميل يقترب من مكافأته.']].map(([n,t,p])=>`<article><span class="section-number">${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section></main><footer class="public-footer"><span>رِجعة · نظام الولاء</span><span>نسخة استعراض — ربط المحافظ والدخول الفعلي عند التشغيل.</span></footer>`;}
function loginHTML(){return `${publicNav()}<main class="auth-layout"><section><div class="eyebrow">مساحة نشاطك وفريقك</div><h1>رقمك، وبداية رجعتك.</h1><p>صاحب النشاط يدخل إلى لوحته. الموظف يدخل مباشرة إلى شاشة تسجيل الزيارات، إذا كان رقمه مضافًا لدى النشاط.</p><div class="tip">${icon('phone')}<div><strong>دخول برمز تحقق.</strong><p>لا تحتاج كلمة مرور. نتحقق من رقم الجوال في كل دخول.</p></div></div><div class="notice">للتجربة: صاحب نشاط مفعّل 0501000001، صاحب نشاط بانتظار التفعيل 0501000002، موظف 0500000001. رمز التجربة 123456؛ لم تُرسل رسالة فعلية.</div></section><section class="panel auth-panel"><h2>تسجيل الدخول</h2><p class="sub">اختر نوع الدخول.</p><div class="segmented mt"><button data-action="login-type" data-type="owner" class="${loginType==='owner'?'active':''}">صاحب النشاط</button><button data-action="login-type" data-type="employee" class="${loginType==='employee'?'active':''}">الموظف</button></div>${loginStep==='phone'?`<form id="phone-login"><label class="field mt"><span>رقم الجوال</span><input class="input" name="phone" type="tel" inputmode="tel" required dir="ltr" placeholder="05xxxxxxxx" autocomplete="tel" value="${esc(loginPhone)}"></label>${loginType==='owner'?`<label class="new-business-option"><input type="checkbox" id="new-business" ${newBusiness?'checked':''}><span><strong>نشاط جديد</strong><small>أنشئ حسابًا وابدأ بمعاينة برنامجك</small></span>${icon('plus')}</label>${newBusiness?`<label class="field"><span>اسم صاحب النشاط</span><input class="input" name="name" maxlength="40" value="${esc(loginName)}" autocomplete="name"></label><label class="field"><span>اسم النشاط</span><input class="input" name="business" maxlength="36" value="${esc(loginBusiness)}"></label>`:''}`:'<div class="notice">يجب أن يضيفك صاحب النشاط برقم جوالك أولًا.</div>'}<p class="error" id="login-error"></p><button class="btn primary full mt" type="submit">المتابعة برمز تحقق</button></form>`:`<form id="phone-login-verify"><label class="field mt"><span>رمز التحقق للرقم <b dir="ltr">${esc(loginPhone)}</b></span><input class="input otp" name="otp" inputmode="numeric" maxlength="6" autocomplete="one-time-code" required dir="ltr"></label><div class="notice">رمز التجربة: <b dir="ltr">123456</b><br>إرسال SMS غير مربوط بعد.</div><p class="error" id="login-error"></p><button class="btn primary full mt" type="submit">تأكيد وتسجيل الدخول</button></form><button class="btn quiet full mt" data-action="login-back">تعديل رقم الجوال</button>`}</section></main>`;}
render=function(){if(publicPage){stopCamera();document.querySelector('#app').innerHTML=publicPage==='home'?homeHTML():loginHTML();return;}originalRender();const top=document.querySelector('.topbar');if(top){const link=document.createElement('button');link.className='btn quiet small';link.dataset.action='home';link.textContent='الرئيسية';top.append(link);}if(role==='owner'||role==='staff'){const a=shopAccount();if(a){const banner=document.createElement('div');banner.className='subscription-banner '+(canOperate()?'activated':'locked');banner.innerHTML=canOperate()?`<span>${icon('check')} الاشتراك مفعّل حتى ${dateLabel(a.subscription.expires)}</span><button class="btn quiet small" data-action="nav" data-view="subscription">تفاصيل الاشتراك</button>`:`<div><strong>${statusNames[statusOf(a)]} · وضع المعاينة</strong><p>تصفح جميع الأقسام. التعديل والإصدار متاحان بعد تفعيل الإدارة.</p></div><button class="btn primary small" data-action="whatsapp">تفعيل عبر واتساب</button>`;document.querySelector('.main')?.prepend(banner);if(!canOperate()){document.querySelectorAll('.main input,.main select,.main textarea').forEach(el=>{if(!el.closest('#token-redeem')&&el.id!=='customer-search')el.disabled=true;});document.querySelectorAll('.main [data-action]').forEach(el=>{if(mutationActions.has(el.dataset.action)){el.disabled=true;el.title='يلزم تفعيل الاشتراك';}});}}}};
const baseSave=save;save=function(){db.accounts??=[];for(const s of db.shops)if(!db.accounts.some(a=>a.shop===s.id))db.accounts.push({id:'USER-'+s.id,name:s.name,phone:'',email:'',shop:s.id,created:Date.now(),subscription:{status:'pending',expires:null,period:null}});baseSave();};
const mutationActions=new Set(['save-card','color','card-icon','pattern','remove-logo','clear-background','clear-stamp','template','add-employee','toggle-employee','simulate-scan','manual-scan','camera','undo','download-qr','copy-link']);
function subscriptionHTML(){const a=shopAccount(),st=statusOf(a);return head('اشتراك رِجعة','بطاقات غير محدودة','اشتراك واحد بـ١٩٩ ريال شهريًا.')+`<div class="grid-two"><section class="panel"><div class="panel-head"><h2>اشتراك نشاطك</h2><span class="pill ${st==='active'?'':'gray'}">${statusNames[st]}</span></div><div class="subscription-details"><div><span>معرّف حسابك</span><b dir="ltr">${esc(a.id)}</b></div><div><span>رقم الجوال</span><b dir="ltr">${esc(a.phone||'غير مضاف')}</b></div><div><span>نهاية الاشتراك</span><b>${dateLabel(a.subscription.expires)}</b></div><div><span>عدد البطاقات</span><b>غير محدود</b></div></div><button class="btn primary full mt" data-action="whatsapp">${st==='active'?'طلب تجديد عبر واتساب':'طلب التفعيل عبر واتساب'}</button></section><section class="panel"><h2>لديك توكن تفعيل؟</h2><p class="sub mt">أدخل التوكن الذي أصدرته الإدارة لهذا الحساب.</p><form id="token-redeem"><label class="field mt"><span>توكن الاشتراك</span><input class="input" name="token" dir="ltr" autocomplete="off" placeholder="RJ-…" required></label><button type="submit" class="btn secondary full">تفعيل الاشتراك</button><p class="error" id="token-error"></p></form><div class="notice">التوكن مرتبط بحساب واحد ويستخدم مرة واحدة. مدة التفعيل يحددها الأدمن.</div></section></div>`;}
function accountRows(accounts){return accounts.length?accounts.map(a=>{const st=statusOf(a),s=db.shops.find(s=>s.id===a.shop);return `<tr><td><strong>${esc(a.name)}</strong><small class="line-meta" style="display:block">${esc(a.email)}</small></td><td>${esc(s.name)}<small class="line-meta" style="display:block" dir="ltr">${esc(a.id)}</small></td><td><span class="pill ${st==='active'?'':st==='pending'?'gold':'gray'}">${statusNames[st]}</span></td><td>${dateLabel(a.subscription.expires)}</td><td><div class="actions"><button class="btn secondary small" data-action="activate-user" data-id="${a.id}" data-period="month">${st==='active'?'تجديد شهر':'تفعيل شهر'}</button><button class="btn secondary small" data-action="activate-user" data-id="${a.id}" data-period="year">${st==='active'?'تجديد سنة':'تفعيل سنة'}</button><button class="btn quiet small" data-action="issue-token" data-id="${a.id}">إصدار توكن</button><button class="btn danger small" data-action="suspend-user" data-id="${a.id}" ${st==='suspended'?'disabled':''}>إيقاف</button><button class="btn quiet small" data-action="open-user" data-id="${a.id}">عرض اللوحة</button></div></td></tr>`;}).join(''):'<tr><td colspan="5" class="empty">لا يوجد مستخدمون مطابقون.</td></tr>';}
function accountsHTML(){return head('إدارة الحسابات','المستخدمون والاشتراكات','التسجيل لا يفعّل الاشتراك. اعتمد الدفع ثم فعّل الحساب.')+`<div class="stats">${[['pending','بانتظار التفعيل'],['active','مفعّلون'],['expired','منتهون'],['suspended','موقوفون']].map(([st,t])=>`<div class="stat"><div class="stat-top">${t}${icon(st==='active'?'check':'users')}</div><div class="stat-value">${fmt(db.accounts.filter(a=>statusOf(a)===st).length)}</div></div>`).join('')}</div><section class="panel"><div class="search-row"><input class="input" id="account-search" placeholder="اسم، رقم جوال، أو معرّف حساب" aria-label="البحث عن مستخدم"><select id="account-filter" class="input" style="max-width:200px"><option value="all">كل الحالات</option>${Object.entries(statusNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>المستخدم</th><th>النشاط</th><th>الحالة</th><th>نهاية الاشتراك</th><th>إدارة الاشتراك</th></tr></thead><tbody id="account-rows">${accountRows(db.accounts)}</tbody></table></div></section><div class="tip">${icon('clock')}<div><strong>التجديد يحفظ الأيام المتبقية.</strong><p>المفعّل يجدد من نهاية اشتراكه، والمنتهي يبدأ من اليوم. الإيقاف يوقف الإجراءات ويحفظ بيانات الحساب.</p></div></div>`;}
function tokensHTML(){return head('تفعيل مضبوط','توكنات الاشتراك','لكل توكن حساب واحد ومدة واحدة واستخدام واحد.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>التوكن</th><th>الحساب</th><th>المدة</th><th>الحالة</th><th>صالح حتى</th><th></th></tr></thead><tbody>${db.tokens.length?db.tokens.map(t=>`<tr><td dir="ltr">${esc(t.code)}</td><td>${esc(db.accounts.find(a=>a.id===t.account)?.name)}</td><td>${t.period==='year'?'سنة':'شهر'}</td><td><span class="pill ${t.used||t.revoked||t.validUntil<Date.now()?'gray':''}">${t.used?'مستخدم':t.revoked?'ملغى':t.validUntil<Date.now()?'منتهي':'جاهز'}</span></td><td>${dateLabel(t.validUntil)}</td><td><button class="btn quiet small" data-action="revoke-token" data-id="${t.id}" ${t.used||t.revoked?'disabled':''}>إلغاء</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">أصدر توكنًا من قائمة المستخدمين.</td></tr>'}</tbody></table></div></section>`;}
function adminLogHTML(){return head('سجل الإدارة','قرارات الاشتراك','التفعيل والتجديد والإيقاف والتوكنات.')+`<section class="panel">${db.adminLogs.length?db.adminLogs.map(l=>`<div class="activity-row"><span class="avatar">${icon('shield')}</span><div class="grow"><strong>${esc(l.action)} · ${esc(l.user)}</strong><small>${esc(l.extra)}</small></div><small>${dateLabel(l.time)}</small></div>`).join(''):'<p class="empty">لا توجد قرارات مسجلة بعد.</p>'}</section>`;}
function signIn(name,phone,business){let a=db.accounts.find(a=>a.phone===phone);if(!a){const sid=crypto.randomUUID();a={id:'USER-'+crypto.randomUUID().slice(0,8).toUpperCase(),name,email:'',phone,shop:sid,created:Date.now(),subscription:{status:'pending',expires:null,period:null}};db.accounts.push(a);db.shops.push({id:sid,name:business,status:'active',branch:'الفرع الرئيسي',card:{...structuredClone(templates[0]),name:business,logo:''},employees:[],members:[],logs:[]});audit('تسجيل حساب جديد',a);}signedAccount=a.id;db.shop=a.shop;db.member=shop().members[0]?.id||'';publicPage='';role='owner';view='overview';draft=null;save();render();}
function blockEvent(event,text){event.preventDefault();event.stopImmediatePropagation();toast(text);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if((role==='owner'||role==='staff')&&!publicPage&&!canOperate()&&mutationActions.has(action)){blockEvent(event,'الاشتراك غير مفعّل. يمكنك التصفح والمعاينة فقط.');return;}if(action==='role'){publicPage='';if(b.dataset.role==='owner')signedAccount=shopAccount()?.id;return;}if(action==='open-shop'){signedAccount=db.accounts.find(a=>a.shop===b.dataset.id)?.id;return;}if(action==='confirm-reset'){setTimeout(()=>location.reload(),0);return;}const own=new Set(['home','login','login-type','login-back','employee-shop','whatsapp','demo-admin','activate-user','confirm-activation','suspend-user','confirm-suspend','issue-token','create-token','revoke-token','open-user','copy-token']);if(!own.has(action))return;event.preventDefault();event.stopImmediatePropagation();if(action==='home'){publicPage='home';render();}else if(action==='login'){publicPage='login';loginStep='phone';render();}else if(action==='login-type'){loginType=b.dataset.type;loginStep='phone';render();}else if(action==='login-back'){loginStep='phone';render();}else if(action==='employee-shop'){enterEmployee(b.dataset.shop,b.dataset.employee);document.querySelector('#modal').close();}else if(action==='whatsapp')whatsapp();else if(action==='demo-admin'){publicPage='';role='admin';view='accounts';render();}else if(action==='open-user'){const a=db.accounts.find(a=>a.id===b.dataset.id);signedAccount=a.id;db.shop=a.shop;publicPage='';role='owner';view='overview';draft=null;save();render();}else if(action==='activate-user'){const a=db.accounts.find(a=>a.id===b.dataset.id);modal('تفعيل الاشتراك',`<p>تفعيل ${esc(a.name)} لمدة ${b.dataset.period==='year'?'سنة':'شهر'}. هل تم اعتماد الدفع عبر واتساب؟</p><div class="notice">لا يتحقق النظام من الدفع تلقائيًا. تأكيدك يسجل اعتماد الدفع والتفعيل.</div>`,`<button class="btn secondary" data-action="close-modal">إلغاء</button><button class="btn primary" data-action="confirm-activation" data-id="${a.id}" data-period="${b.dataset.period}">اعتماد الدفع والتفعيل</button>`);}else if(action==='confirm-activation'){const a=db.accounts.find(a=>a.id===b.dataset.id);activate(a,b.dataset.period);document.querySelector('#modal').close();render();toast('تم تفعيل الاشتراك.');}else if(action==='suspend-user'){modal('إيقاف الاشتراك','<p>سيتحول الحساب إلى المعاينة وتُلغى توكناته غير المستخدمة، مع حفظ بطاقاته وبياناته.</p>',`<button class="btn danger" data-action="confirm-suspend" data-id="${b.dataset.id}">إيقاف الحساب</button>`);}else if(action==='confirm-suspend'){const a=db.accounts.find(a=>a.id===b.dataset.id);a.subscription.status='suspended';db.tokens.filter(t=>t.account===a.id&&!t.used).forEach(t=>t.revoked=true);audit('إيقاف الحساب',a);save();document.querySelector('#modal').close();render();}else if(action==='issue-token'){modal('إصدار توكن اشتراك',`<p>التوكن مرتبط بـ${esc(db.accounts.find(a=>a.id===b.dataset.id).name)}. صالح للاستخدام خلال ٧ أيام.</p><label class="field mt"><span>مدة الاشتراك</span><select id="token-period"><option value="month">شهر</option><option value="year">سنة</option></select></label><label class="terms"><input type="checkbox" id="payment-approved"> تم اعتماد الدفع عبر واتساب</label>`,`<button class="btn primary" data-action="create-token" data-id="${b.dataset.id}">إصدار التوكن</button>`);}else if(action==='create-token'){if(!document.querySelector('#payment-approved').checked){toast('اعتمد الدفع قبل إصدار التوكن.');return;}const t={id:crypto.randomUUID(),code:'RJ-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('').toUpperCase(),account:b.dataset.id,period:document.querySelector('#token-period').value,validUntil:Date.now()+7*86400000,used:false,revoked:false};db.tokens.push(t);audit('إصدار توكن',db.accounts.find(a=>a.id===t.account),t.period==='year'?'سنة':'شهر');save();modal('التوكن جاهز',`<p>أرسله لصاحب هذا الحساب عبر قناة التواصل المعتمدة.</p><input class="input mt" dir="ltr" readonly id="issued-token" value="${esc(t.code)}">`,`<button class="btn primary" data-action="copy-token">نسخ التوكن</button>`);}else if(action==='copy-token'){navigator.clipboard?.writeText(document.querySelector('#issued-token').value).then(()=>toast('تم نسخ التوكن.')).catch(()=>toast('حدد التوكن وانسخه يدويًا.'));}else if(action==='revoke-token'){const t=db.tokens.find(t=>t.id===b.dataset.id);t.revoked=true;audit('إلغاء توكن',db.accounts.find(a=>a.id===t.account));save();render();}},true);
document.addEventListener('submit',event=>{const f=event.target;if(!publicPage&&(role==='owner'||role==='staff')&&!canOperate()&&f.id!=='token-redeem'){blockEvent(event,'يلزم تفعيل الاشتراك قبل تنفيذ الإجراء.');return;}if(f.id==='join-form'&&!canOperate()){blockEvent(event,'إصدار البطاقات متوقف إلى أن يتم تفعيل اشتراك النشاط.');return;}if(f.id==='phone-login'){event.preventDefault();event.stopImmediatePropagation();const d=new FormData(f);const phone=normalizePhone(d.get('phone'));if(!phone){document.querySelector('#login-error').textContent='أدخل رقم جوال سعودي صحيحًا.';return;}loginPhone=phone;loginName=String(d.get('name')||'').trim();loginBusiness=String(d.get('business')||'').trim();if(loginType==='owner'&&newBusiness&&db.accounts.some(a=>a.phone===phone)){document.querySelector('#login-error').textContent='هذا الرقم مسجل بالفعل. ألغِ خيار نشاط جديد لتسجيل الدخول.';return;}if(loginType==='owner'&&!newBusiness&&!db.accounts.some(a=>a.phone===phone)){document.querySelector('#login-error').textContent='الرقم غير مسجل. فعّل خيار نشاط جديد لإنشاء حساب.';return;}if(loginType==='owner'&&newBusiness&&(!loginName||!loginBusiness)){document.querySelector('#login-error').textContent='لإنشاء حساب جديد، أدخل اسمك واسم النشاط.';return;}if(loginType==='employee'&&!db.shops.some(s=>s.employees.some(e=>e.phone===phone&&e.status==='active'))){document.querySelector('#login-error').textContent='رقمك غير مضاف كموظف نشط. تواصل مع صاحب النشاط.';return;}loginStep='otp';render();}if(f.id==='phone-login-verify'){event.preventDefault();event.stopImmediatePropagation();if(new FormData(f).get('otp')!=='123456'){document.querySelector('#login-error').textContent='رمز التجربة غير صحيح.';return;}if(loginType==='owner')signIn(loginName,loginPhone,loginBusiness);else{const matches=db.shops.flatMap(s=>s.employees.filter(e=>e.phone===loginPhone&&e.status==='active').map(e=>({s,e})));if(matches.length===1)enterEmployee(matches[0].s.id,matches[0].e.id);else if(matches.length)modal('اختر النشاط',matches.map(({s,e})=>`<button class="btn secondary full mt" data-action="employee-shop" data-shop="${s.id}" data-employee="${e.id}">${esc(s.name)}</button>`).join(''));else toast('أوقف صاحب النشاط وصولك.');}}if(f.id==='token-redeem'){event.preventDefault();event.stopImmediatePropagation();const code=String(new FormData(f).get('token')).trim().toUpperCase(),t=db.tokens.find(t=>t.code===code),a=shopAccount();let error='';if(!t)error='التوكن غير صحيح.';else if(t.account!==a.id)error='هذا التوكن يخص حسابًا آخر.';else if(t.used)error='استُخدم هذا التوكن سابقًا.';else if(t.revoked)error='ألغت الإدارة هذا التوكن.';else if(t.validUntil<Date.now())error='انتهت صلاحية التوكن.';else if(statusOf(a)==='suspended')error='الحساب موقوف. تواصل مع الإدارة.';if(error){document.querySelector('#token-error').textContent=error;return;}t.used=true;t.usedAt=Date.now();activate(a,t.period,'token');render();toast('تم تفعيل اشتراكك.');}},true);
function filterAccounts(){const q=document.querySelector('#account-search')?.value.toLowerCase()||'',st=document.querySelector('#account-filter')?.value||'all';const rows=document.querySelector('#account-rows');if(rows)rows.innerHTML=accountRows(db.accounts.filter(a=>(st==='all'||statusOf(a)===st)&&`${a.name} ${a.phone} ${a.id}`.toLowerCase().includes(q)));}
document.addEventListener('input',e=>{if(e.target.id==='account-search')filterAccounts();});document.addEventListener('change',e=>{if(e.target.id==='account-filter')filterAccounts();if(e.target.id==='new-business'){loginPhone=document.querySelector('#phone-login [name=phone]').value;newBusiness=e.target.checked;render();}});
function enterEmployee(sid,eid){db.shop=sid;signedAccount=shopAccount().id;staffEmployee=eid;publicPage='';role='staff';view='scan';lastTx=null;selectedStaffMember='';save();render();}
setInterval(()=>{if(!publicPage&&(role==='owner'||role==='staff')&&!canOperate()&&stream)stopCamera();},3000);save();render();
